mapper.select:
SELECT DATE_FORMAT(`collect_time`, '%Y-%m-%d %H:%i:%s') AS `collectTime`, `channel_no` AS `channelNo`, `set_weight` AS `setWeight`, `actual_weight` AS `actualWeight`, `deviation` AS `deviation`, `is_over` AS `isOver`, `line_speed` AS `lineSpeed`, `prd_order_no` AS `prdOrderNo` FROM `mes_weight_sample` WHERE `device_id` = #{deviceId} AND `deleted` = 0
AND `channel_no` = #{channelNo}
AND `collect_time` >= #{from}
AND `collect_time` <= #{to}
ORDER BY `collect_time` DESC, `channel_no` ASC LIMIT #{limit}

SELECT `channel_no` AS `channelNo`, COUNT(*) AS `sampleCount`, ROUND(AVG(`actual_weight`), 3) AS `avgWeight`, ROUND(MIN(`actual_weight`), 3) AS `minWeight`, ROUND(MAX(`actual_weight`), 3) AS `maxWeight`, ROUND(AVG(`deviation`), 4) AS `avgDeviation`, ROUND(AVG(`deviation_pct`), 3) AS `avgDeviationPct`, SUM(CASE WHEN `is_over` = 1 THEN 1 ELSE 0 END) AS `overCount`, ROUND(SUM(CASE WHEN `is_over` = 1 THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS `overRatePct` FROM `mes_weight_sample` WHERE `device_id` = #{deviceId} AND `deleted` = 0
AND `collect_time` >= #{from}
AND `collect_time` <= #{to}
GROUP BY `channel_no` ORDER BY `channel_no` ASC
